// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numCalls) public {
        uint256 sum = 0;
        for (uint8 i = 0; i < numCalls; i++) {
            address actor = address(uint160(uint256(keccak256(abi.encodePacked(i)))));
            uint256 amount = uint256(keccak256(abi.encodePacked(i, "amount"))) % (type(uint256).max / numCalls) + 1;
            vm.deal(actor, amount);
            vm.prank(actor);
            c.Deposit{value: amount}();
            sum += amount;
        }
        assertEq(sum, address(c).balance, "Invariant: sum(balances) == address(c).balance");
    }
}

