pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // ensure depositor is not the zero address
        vm.assume(depositor != address(0));
        // ensure amount is non-zero so we always observe a meaningful change
        vm.assume(amount > 0);
        // initialize the contract
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        // read initial balance
        uint256 initialBalance = c.balances(depositor);
        // prepare deposit
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.Deposit{value: amount}();
        // read final balance
        uint256 finalBalance = c.balances(depositor);
        // invariant: finalBalance == initialBalance + amount
        assertTrue(finalBalance == initialBalance + amount);
    }
}

