pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(1);
        c.Initialized();
    }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositor != address(this));
        vm.assume(depositor != address(c));
        vm.assume(collectAmount > 0);
        vm.assume(depositAmount > 0);
        uint256 preMinSum = c.MinSum();
        uint256 preBal = c.balances(depositor);
        uint256 expectedBal = preBal + depositAmount;
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();
        uint256 postBal = c.balances(depositor);
        if (expectedBal >= preBal) {
            assertEq(postBal, expectedBal);
        } else {
            assertLt(postBal, preBal);
        }
        if (postBal >= preMinSum && postBal >= collectAmount) {
            vm.deal(address(c), collectAmount);
            vm.prank(depositor);
            bool ok = true;
            try c.Collect(collectAmount) {} catch { ok = false; }
            uint256 afterCollectBal = c.balances(depositor);
            if (ok) {
                assertEq(afterCollectBal, postBal - collectAmount);
            } else {
                assertEq(afterCollectBal, postBal);
            }
        }
    }
}

