pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 depositAmount) public {
        // 1. Restrict admissible domain: depositor must be distinct from the test contract
        vm.assume(depositor != address(this));
        // Keep amounts wide; only exclude zero to make deposit meaningful
        vm.assume(depositAmount > 0);

        // 2. Record pre-state balance
        uint256 preBalance = c.balances(depositor);

        // 3. Fund and execute deposit as the fuzzed depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // 4. Observe post-state balance
        uint256 postBalance = c.balances(depositor);

        // 5. General rule: the reference contract enforces that the post-balance
        //    equals the pre-balance + depositAmount ONLY when no overflow occurs;
        //    otherwise it reverts. The mutant removes the overflow check and
        //    always modifies the balance, causing a discrepancy when overflow occurs.
        //    We assert that if the transaction succeeds (no revert), the balance
        //    relation must be consistent with safe arithmetic integrity.
        //    Concretely: the reference MUST either revert OR satisfy the invariant
        //    postBalance >= preBalance && postBalance - preBalance == depositAmount.
        //    The mutant violates this by allowing a non-reverting wrap-around.
        bool invariantHolds = (postBalance >= preBalance) && (postBalance - preBalance == depositAmount);
        assertTrue(invariantHolds);
    }
}

