pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount) public {
        // Keep the deposited amount in a wide admissible range (non-zero to trigger the bug)
        vm.assume(amount > 0);
        // Prevent overflow in the invariant computation
        vm.assume(amount <= type(uint128).max);

        address depositor = address(0x1234);
        vm.deal(depositor, amount);

        // Record the sum of balances before deposit
        uint256 totalBalancesBefore = c.balances(depositor);

        vm.prank(depositor);
        c.Deposit{value: amount}();

        // Sum of all balances after deposit (only depositor has non-zero balance in this test)
        uint256 totalBalancesAfter = c.balances(depositor);

        // Invariant: total balance increase equals the deposited amount
        // Correct: balances[depositor] increases by amount
        // Mutant: balances[depositor] is set to 0, so increase is 0 (breaks when amount > 0)
        assertTrue(totalBalancesAfter - totalBalancesBefore == amount);
    }
}

