pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Restrict to reasonable amounts to prevent overflow
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= type(uint128).max);

        // Setup: initialize with MinSum = 0 so any deposit allows collecting
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit from an account
        address alice = address(0x1234);
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        c.Deposit{value: depositAmount}();

        // Now, since SetMinSum can be changed by the bug, a call to SetMinSum with a huge value
        // will prevent collecting. We test the invariant that if collectAmount <= balance and
        // MinSum <= balance, the collect must succeed and reduce the balance.
        // We set MinSum to something <= balance to ensure the condition holds initially.
        uint256 balanceBefore = c.balances(alice);
        vm.assume(collectAmount <= balanceBefore);
        c.SetMinSum(balanceBefore); // This call is allowed in reference (no effect after init), but in bug it changes MinSum

        // Try collect
        vm.prank(alice);
        try c.Collect(collectAmount) {
            // If collect succeeded, balance must decrease by exactly collectAmount
            uint256 balanceAfter = c.balances(alice);
            assertEq(balanceAfter, balanceBefore - collectAmount, "Balance must decrease by collected amount");
        } catch {
            // If collect reverted, it's because MinSum was changed (bug) or because of some edge case.
            // The reference will always succeed here because MinSum was set to balanceBefore and initialized, so MinSum <= balanceBefore.
            // The bug will revert if MinSum was changed to a value > balanceBefore (which is impossible here since we set it to balanceBefore).
            // Actually, we need a case where the bug changes MinSum so that collect fails when it should succeed.
            // We want to assert that if MinSum <= balance, collect must succeed.
            // So we check MinSum after the call and assert that if MinSum > balance, the revert is expected (bug), otherwise it's a failure.
            uint256 minSumAfter = c.MinSum();
            assertLe(minSumAfter, balanceBefore, "Collect reverted even though MinSum <= balance");
        }
    }
}

