pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // Ensure we are in the uninitialized state where SetMinSum does not revert
        vm.assume(!c.intitalized());
        // Call SetMinSum with the fuzzed value
        c.SetMinSum(_val);
        // Attempt to initialize; this may fail if intitalized is false but the bug causes revert
        bool initOk;
        try c.Initialized() { initOk = true; } catch { initOk = false; }
        // If initialization succeeded, MinSum should equal _val (reference) or 0 (buggy)
        // If initialization failed, the MinSum getter will revert due to uninitialized state
        if (initOk) {
            // Initialization succeeded: reference sets MinSum to _val, bug sets it to 0
            // For the bug to be detected, we need _val != 0, which is handled by the fuzzer
            assertTrue(c.MinSum() == _val);
        } else {
            // Initialization reverted; this is the bug case where init reverted unexpectedly
            // In the reference, init never reverts after SetMinSum; in the bug it does
            assertTrue(false);
        }
    }
}

