pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 minSum, uint128 depositAmt, uint128 collectAmt) public {
        // Ensure collectAmt is strictly greater than depositAmt so balance < collectAmt
        vm.assume(collectAmt > depositAmt);
        // Ensure minSum is not too large to be satisfied by deposit
        vm.assume(minSum <= depositAmt);

        // Initialize contract with minSum
        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1));
        c.Initialized();

        // Deploy reentrant attacker that will call Collect in receive
        ReentrantCollector attacker = new ReentrantCollector(c);

        // Fund attacker with deposit amount
        vm.deal(address(attacker), depositAmt);

        // Attacker deposits
        attacker.deposit{value: depositAmt}();

        // Attacker attempts to collect collectAmt > balance
        uint256 balanceBefore = address(attacker).balance;
        attacker.triggerCollect(collectAmt);
        uint256 balanceAfter = address(attacker).balance;

        // Reentrant attacker should not gain more than its legitimate balance
        // In reference, Collect reverts (balance < _am), so balanceAfter == balanceBefore
        // In mutant, Collect succeeds, underflow occurs, and reentrant call drains excess
        assertTrue(balanceAfter <= balanceBefore + depositAmt);
    }
}

contract ReentrantCollector {
    C target;
    bool attacking;

    constructor(C _target) {
        target = _target;
    }

    function deposit() public payable {
        target.Deposit{value: msg.value}();
    }

    function triggerCollect(uint256 amt) public {
        attacking = true;
        target.Collect(amt);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter Collect while in collect, drain more funds
            target.Collect(address(target).balance);
        }
    }
}

