        c.SetMinSum(0);
        c.SetLogFile(address(0x0000000000000000000000000000000000000001));
        c.Initialized();

        // give the sender twice the intended collection amount so the checks pass
        uint256 depositAmount = _am * 2;
        vm.deal(_sender, depositAmount);
        vm.prank(_sender);
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(_sender);

        vm.prank(_sender);
        c.Collect(_am);

        uint256 balAfter = c.balances(_sender);

        // invariants: after collecting _am, balAfter + _am must equal balBefore
        // (the reference respects this; the bug sets balAfter = _am, so balAfter + _am = 2*_am which differs from balBefore whenever _am != 0)
        assertTrue(balAfter + _am == balBefore);
    }
}

