pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 _amount) public {
        vm.assume(_amount > 0);

        // Initialize contract and set MinSum to allow collect
        c.SetMinSum(0);
        c.Initialized();

        // Deploy an adversarial helper that will revert so caller cannot steal ether,
        // but we still observe the balance change (or lack thereof) from the Collect attempt.
        Reverter reverter = new Reverter();
        address caller = address(reverter);

        // Fund caller
        vm.deal(caller, _amount + 1 ether);

        // Deposit into c from caller
        vm.prank(caller);
        c.Deposit{value: _amount}();

        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = caller.balance;

        // Attempt Collect; the helper will revert, but that revert only affects the ETH send,
        // not the balance deduction in the reference contract.
        vm.prank(caller);
        try c.Collect(_amount) {} catch {}

        uint256 contractBalanceAfter = address(c).balance;
        uint256 callerBalanceAfter = caller.balance;

        // Reference rule: A Collect attempt that reverts during ETH send still deducts the balance,
        // so the contract balance should decrease (ether burned) and caller balance unchanged.
        // Mutant: balance not deducted, so contract balance unchanged or only gas cost change.
        // We assert: contract balance decreases by exactly _amount (if balance deduction happened)
        // vs almost no change if mutant. Use a simple delta check.
        assertTrue(contractBalanceBefore - contractBalanceAfter == _amount);
    }
}

contract Reverter {
    // Adversarial helper: receives ETH but reverts to simulate a failing collect recipient
    fallback() external payable {
        revert("Reverter: forced failure");
    }
}

