        // The call may revert in the mutant when balance is in [amount, 2*amount-1]
        // but should succeed in the original. We capture success/revert via try/catch.
        bool success;
        try c.Collect(amount) {
            success = true;
        } catch {
            success = false;
        }

        uint256 postBalance = c.balances(caller);

        if (success) {
